//! One tiny Lua script per API method, overload and argument shape, read from oracle/cov/lua and generated by
//! tools_coverage.py. Each script is compiled by the original LuaC (the oracle); its output is in oracle/cov/or.
//! Rust must fail when the oracle failed, and must produce identical bytes when the oracle succeeded.
//! No game files are needed.
use std::path::PathBuf;

/// Returns the oracle/cov folder, resolved from CARGO_MANIFEST_DIR as ../oracle/cov.
fn cov() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../oracle/cov")
}

/// Compiles every file in oracle/cov/lua and compares the result with the oracle output in oracle/cov/or.
/// A case passes when both succeed with identical bytes, or both fail. Any other combination is a mismatch.
#[test]
fn every_generated_case_matches_the_oracle() {
    // The corpus must hold more than 800 files, so an empty or partial corpus fails the test.
    let mut files: Vec<PathBuf> = std::fs::read_dir(cov().join("lua")).unwrap().map(|e| e.unwrap().path()).collect();
    files.sort();
    assert!(files.len() > 800, "expected the generated corpus, found {}", files.len());
    let (mut same, mut both_fail, mut bad) = (0, 0, vec![]);
    for f in &files {
        let stem = f.file_stem().unwrap().to_string_lossy().to_string();
        // Files named dpl_* are DPL packages (oracle output ends in .sp). All other files are missions (oracle output ends in .mpc).
        let dpl = stem.starts_with("dpl_");
        let oracle_out = cov().join("or").join(format!("{stem}.{}", if dpl { "sp" } else { "mpc" }));
        let path = f.to_str().unwrap();
        let ours = if dpl { zartex_core::api_dpl::compile_dpl_file(path) } else { zartex_core::compile::compile_file(path) };
        // A missing oracle output file means the oracle failed on this script.
        match (oracle_out.exists(), ours) {
            (true, Ok(b)) => {
                if b == std::fs::read(&oracle_out).unwrap() {
                    same += 1
                } else {
                    bad.push(format!("{stem}: bytes differ"))
                }
            }
            (false, Err(_)) => both_fail += 1,
            (true, Err(e)) => bad.push(format!("{stem}: oracle ok, rust failed: {e}")),
            (false, Ok(_)) => bad.push(format!("{stem}: oracle failed, rust ok")),
        }
    }
    println!("identical: {same}, both failed: {both_fail}");
    assert!(bad.is_empty(), "{} mismatches:\n{}", bad.len(), bad.join("\n"));
}
